"""Scientific audit records: everything needed to reproduce (and judge) a processing run."""
from __future__ import annotations

import json
import platform
from datetime import datetime, timezone
from functools import lru_cache
from importlib import metadata

from app import __version__

OUTPUT_LABEL = (
    "Computationally processed output generated by LabClarity AI (may include AI models). Not verified scientific data: "
    "processing may suppress or synthesise detail. The original image is preserved separately."
)
_PACKAGES = ("numpy", "scikit-image", "pillow", "torch", "spandrel")


@lru_cache(maxsize=1)
def software_versions() -> dict:
    versions = {"labclarityAiService": __version__, "python": platform.python_version()}
    for package in _PACKAGES:
        try:
            versions[package] = metadata.version(package)
        except metadata.PackageNotFoundError:
            versions[package] = None
    return versions


def intensity_preserving(steps: list[dict]) -> bool:
    """Contrast remapping breaks the link between pixel values and measured intensity."""
    return not any(step["op"] == "contrast" for step in steps)


def build_audit(*, image, roi, steps, output, output_bit_depth, quality, diff_stats, device, duration_ms):
    return {
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "software": software_versions(),
        "device": device,
        "input": {
            "width": image.width,
            "height": image.height,
            "channels": image.channels,
            "bitDepth": image.norm.bit_depth,
            "normalization": {
                "low": image.norm.low,
                "high": image.norm.high,
                "method": "linear /255" if image.norm.bit_depth == 8 else "percentile 0.1-99.9",
            },
            "roi": roi.model_dump() if roi else None,
        },
        "steps": steps,
        "output": {
            "width": int(output.shape[1]),
            "height": int(output.shape[0]),
            "channels": int(output.shape[-1]),
            "dataBitDepth": output_bit_depth,
            "intensityPreserving": intensity_preserving(steps),
            "label": OUTPUT_LABEL,
        },
        "quality": quality,
        "difference": diff_stats,
        "durationMs": duration_ms,
    }


def png_label(audit: dict) -> dict:
    """Compact provenance embedded into every output PNG as text chunks."""
    summary = {
        "timestamp": audit["timestamp"],
        "steps": [
            {"op": s["op"], "method": s["method"], "params": s["params"],
             "model": (s["model"] or {}).get("id"), "weightsSha256": (s["model"] or {}).get("weightsSha256")}
            for s in audit["steps"]
        ],
        "roi": audit["input"]["roi"],
        "software": audit["software"],
    }
    return {
        "Software": f"LabClarity AI {audit['software']['labclarityAiService']}",
        "Description": OUTPUT_LABEL,
        "LabClarity-Provenance": json.dumps(summary, separators=(",", ":")),
    }
